//! Pairing and token logic (`docs/specs/2026-11-01-pairing-and-trust.md`), without OS calls.
//!
//! - [`sas`]: the short authentication string both screens show.
//! - [`token`]: token hashing, the constant-time comparison and the device-table lookup.
//! - [`qr`]: the `gander://pair` payload of flow A (builder and parser).
//! - [`window`]: the pairing window state machine (open / closed / expired / attempts, one pending
//!   request, approve / deny / poll / collect).
//!
//! Randomness (window secret, host nonce, tokens, pairing ids) is generated by the caller from the
//! OS CSPRNG and passed in, so this crate stays free of OS calls and the state machine is
//! deterministic under test. Time is passed in as [`std::time::Instant`].

pub mod qr;
pub mod sas;
pub mod token;
pub mod window;

use base64::Engine as _;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;

/// Length of the device and host nonces, in bytes.
pub const NONCE_LEN: usize = 16;

/// Length of the pairing-window secret and of a token, in bytes.
pub const SECRET_LEN: usize = 32;

/// base64url without padding (the form of every nonce, secret and token on the wire).
pub fn b64url(bytes: &[u8]) -> String {
    URL_SAFE_NO_PAD.encode(bytes)
}

/// Decodes base64url without padding into exactly `N` bytes. `None` on any other input
/// (padding, standard-alphabet characters, wrong length).
pub fn b64url_fixed<const N: usize>(text: &str) -> Option<[u8; N]> {
    // Upper bound on the encoded length of N bytes, checked before decoding anything.
    if text.len() > N.div_ceil(3) * 4 {
        return None;
    }
    let bytes = URL_SAFE_NO_PAD.decode(text).ok()?;
    bytes.try_into().ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn b64url_fixed_is_strict() {
        let n = [7u8; NONCE_LEN];
        let text = b64url(&n);
        assert_eq!(text.len(), 22);
        assert_eq!(b64url_fixed::<NONCE_LEN>(&text), Some(n));
        assert_eq!(b64url_fixed::<NONCE_LEN>(&format!("{text}==")), None);
        assert_eq!(b64url_fixed::<NONCE_LEN>(&text[..21]), None);
        assert_eq!(b64url_fixed::<SECRET_LEN>(&text), None);
        assert_eq!(b64url_fixed::<NONCE_LEN>("+/+/+/+/+/+/+/+/+/+/+/"), None);
        assert_eq!(b64url_fixed::<NONCE_LEN>(&"A".repeat(10_000)), None);
    }
}
